import{_ as a,o as s,c as t,S as n}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"Linux下恢复误删除的文件","description":"经常有时候喜欢删除文件...但是之后又后悔删除... Linux 下 rm 之后是没有回收站的.\\n于是我便寻找恢复文件的相关资料.","frontmatter":{"title":"Linux下恢复误删除的文件","date":"2014-07-21 17:39","comments":true,"archives":2014,"tags":["linux"]},"headers":[],"relativePath":"posts/2014-07-21-linux-undelete-files/index.md","filePath":"posts/2014/2014-07-21-Linux-undelete-files.md"}'),i={name:"posts/2014-07-21-linux-undelete-files/index.md"};function r(l,e,o,d,p,c){return s(),t("div",null,[...e[0]||(e[0]=[n('<p>经常有时候喜欢删除文件...但是之后又后悔删除... Linux 下 rm 之后是没有回收站的.<br> 于是我便寻找恢复文件的相关资料.</p><h2 id="testdisk" tabindex="-1">TestDisk <a class="header-anchor" href="#testdisk" aria-label="Permalink to &quot;TestDisk&quot;">​</a></h2><p>TestDisk 是用来帮助恢复丢失的分区和使无法启动的启动盘再次启动.<br> 使用 TestDisk 之前别忘了备份分区表.</p><h3 id="备份分区表" tabindex="-1">备份分区表 <a class="header-anchor" href="#备份分区表" aria-label="Permalink to &quot;备份分区表&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># sfdisk -d /dev/sda &gt; /tmp/sda.bak</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="恢复分区表" tabindex="-1">恢复分区表 <a class="header-anchor" href="#恢复分区表" aria-label="Permalink to &quot;恢复分区表&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># sfdisk /dev/sda &lt; /tmp/sda.bak</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>官方教程:<a href="http://www.cgsecurity.org/wiki/TestDisk_Step_By_Step" target="_blank" rel="noreferrer">TestDisk Step By Step</a></p><h2 id="photorec" tabindex="-1">PhotoRec <a class="header-anchor" href="#photorec" aria-label="Permalink to &quot;PhotoRec&quot;">​</a></h2><p>PhotoRec 是用来恢复丢失的文件和照片.即使重新格式化或严重损坏的文件系统都可以恢复. 但是 PhotoRec 只有全盘扫描和空闲分区扫描.耗时很长.对于自己无意中删除的小文件来说就是 杀鸡焉用牛刀.没有这个必要.</p><h2 id="extundelete" tabindex="-1">Extundelete <a class="header-anchor" href="#extundelete" aria-label="Permalink to &quot;Extundelete&quot;">​</a></h2><p>Extundelete 设计的就是用来从 ext3 或 ext4 的分区恢复最近被删除的文件.它可以从一个相对路径恢复 被删除的文件,非常实用.但是只有当分区被卸载才可以使用.</p><h3 id="恢复被删除的文件" tabindex="-1">恢复被删除的文件 <a class="header-anchor" href="#恢复被删除的文件" aria-label="Permalink to &quot;恢复被删除的文件&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># extundelete --restore-file tux/cv.tex /dev/sda4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="恢复被删除的文件目录" tabindex="-1">恢复被删除的文件目录 <a class="header-anchor" href="#恢复被删除的文件目录" aria-label="Permalink to &quot;恢复被删除的文件目录&quot;">​</a></h3><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># extundelete --restore-directory tux/Documents/tex/ /dev/sda4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Arch wiki:<a href="https://wiki.archlinux.org/index.php/File_recovery" target="_blank" rel="noreferrer">File recovery</a></p>',17)])])}const b=a(i,[["render",r]]);export{h as __pageData,b as default};
